def dump_map():
    # find bounds of known cells
    xs = [i for j in range(N) for i in range(N) if occ[j*N+i]] 
    if not xs: return
    js = [j for j in range(N) for i in range(N) if occ[j*N+i]]
    i0, i1, j0, j1 = min(xs), max(xs), min(js), max(js)
    rc = idx(odo.x, odo.y)
    lines = []
    for j in range(j1, j0-1, -1):
